package com.yeeyuan;
import java.time.*;
import java.sql.Timestamp;
import java.util.*;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import static com.yeeyuan.Db.*;
@Service
public class Orders {
 public record CartLine(@NotNull UUID productId,@Min(1) @Max(10) int quantity,@NotNull List<UUID> optionChoiceIds,@Size(max=200) String note){}
 public record QuoteInput(@NotNull String mode,UUID visitId,@NotEmpty @Size(max=20) List<@Valid CartLine> items){}
 public record Create(@NotNull UUID quoteId,@Size(max=80) String pickupName){}
 final Db db;final Crypto crypto;final Settings config;
 public Orders(Db db,Crypto crypto,Settings config){this.db=db;this.crypto=crypto;this.config=config;}
 @SuppressWarnings("unchecked") static List<Map<String,Object>> maps(Object v){return (List<Map<String,Object>>)v;}
 @Transactional public Map<String,Object> quote(Auth.User user,QuoteInput req){if(!Set.of("DINE_IN","TAKEAWAY").contains(req.mode))throw Problem.bad("รูปแบบรับอาหารไม่ถูกต้อง");var store=db.one("SELECT * FROM store LIMIT 1 FOR SHARE");if(!Boolean.TRUE.equals(store.get("accepting_orders")))throw new Problem(409,"STORE_CLOSED","ร้านพักรับออเดอร์ชั่วคราว");if(req.mode.equals("DINE_IN"))visit(user,req.visitId);else if(req.visitId!=null)throw Problem.bad("กลับบ้านไม่ต้องระบุโต๊ะ");List<Map<String,Object>> lines=new ArrayList<>();long subtotal=0;
  for(var item:req.items){var p=db.one("SELECT * FROM product WHERE id=? AND active=true AND sold_out=false",item.productId);var groups=db.jdbc.queryForList("SELECT g.* FROM option_group g JOIN product_option_group pg ON pg.group_id=g.id WHERE pg.product_id=?",item.productId);Set<UUID> requested=new HashSet<>(item.optionChoiceIds);if(requested.size()!=item.optionChoiceIds.size())throw Problem.bad("ตัวเลือกซ้ำ");List<Map<String,Object>> selected=new ArrayList<>();int matched=0;long extra=0;
   for(var g:groups){var options=db.jdbc.queryForList("SELECT * FROM option_choice WHERE group_id=? AND active=true",uuid(g,"id"));int n=0;for(var c:options)if(requested.contains(uuid(c,"id"))){n++;matched++;extra=Math.addExact(extra,num(c,"price_delta_satang"));selected.add(Map.of("id",c.get("id"),"group",g.get("name"),"label",c.get("label"),"priceDeltaSatang",c.get("price_delta_satang")));}if(n<num(g,"min_select")||n>num(g,"max_select"))throw Problem.bad("กรุณาเลือก "+str(g,"name")+" ให้ครบ");}
   if(matched!=requested.size())throw Problem.bad("ตัวเลือกไม่ตรงกับสินค้า");long total=Math.multiplyExact(item.quantity,Math.addExact(num(p,"price_satang"),extra));subtotal=Math.addExact(subtotal,total);lines.add(Map.of("productId",item.productId,"name",p.get("name"),"quantity",item.quantity,"unitBaseSatang",p.get("price_satang"),"unitOptionsSatang",extra,"lineTotalSatang",total,"station",p.get("station"),"options",selected,"note",item.note==null?"":item.note));
  }
  long packaging=req.mode.equals("TAKEAWAY")?num(store,"packaging_fee_satang"):0,total=Math.addExact(subtotal,packaging);if(total<2000||total>500000)throw Problem.bad("ยอดชำระต้องอยู่ระหว่าง 20 ถึง 5,000 บาท");UUID id=UUID.randomUUID();Instant expiry=Instant.now().plusSeconds(120);Map<String,Object> calc=Map.of("id",id,"subtotalSatang",subtotal,"packagingFeeSatang",packaging,"totalSatang",total,"expiresAt",expiry.toString(),"lines",lines);db.jdbc.update("INSERT INTO quote(id,customer_id,store_id,visit_id,mode,request,calculated,catalog_version,expires_at) VALUES(?,?,?,?,?,?::jsonb,?::jsonb,?,?)",id,user.id(),uuid(store,"id"),req.visitId,req.mode,db.encode(req),db.encode(calc),num(store,"catalog_version"),Timestamp.from(expiry));return calc;
 }
 void visit(Auth.User u,UUID visit){if(visit==null)throw Problem.bad("กรุณาเข้าร่วมโต๊ะก่อนสั่ง");if(db.jdbc.queryForList("SELECT v.id FROM table_visit v JOIN table_visit_member m ON m.visit_id=v.id WHERE v.id=? AND m.user_id=? AND v.status='OPEN' AND v.expires_at>now() FOR SHARE OF v",visit,u.id()).isEmpty())throw new Problem(403,"INVALID_VISIT","รอบโต๊ะหมดอายุหรือไม่มีสิทธิ์");}
 Map<String,Object> cached(Auth.User u,String path,UUID key,Object body){if(key==null)throw Problem.bad("ต้องมี Idempotency-Key");db.jdbc.queryForObject("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",Object.class,u.id()+path+key);var rows=db.jdbc.queryForList("SELECT * FROM idempotency_record WHERE principal_id=? AND method='POST' AND path=? AND key=?",u.id(),path,key);if(rows.isEmpty())return null;var r=rows.get(0);if(!Crypto.equal(str(r,"request_hash"),Crypto.hash(db.encode(body))))throw new Problem(409,"IDEMPOTENCY_CONFLICT","คีย์เดิมมีข้อมูลต่างกัน");return db.decode(r.get("response_body"));}
 void cache(Auth.User u,String path,UUID key,Object body,Map<String,Object> response){db.jdbc.update("INSERT INTO idempotency_record(principal_id,method,path,key,request_hash,state,response_code,response_body,expires_at) VALUES(?,'POST',?,?,?,'COMPLETED',201,?::jsonb,now()+interval '7 days')",u.id(),path,key,Crypto.hash(db.encode(body)),db.encode(response));}
 @Transactional public Map<String,Object> create(Auth.User u,Create req,UUID key){var cached=cached(u,"/orders",key,req);if(cached!=null)return cached;var quote=db.one("SELECT * FROM quote WHERE id=? AND customer_id=? FOR UPDATE",req.quoteId,u.id());var store=db.one("SELECT * FROM store WHERE id=? FOR SHARE",uuid(quote,"store_id"));if(!Boolean.TRUE.equals(store.get("accepting_orders")))throw new Problem(409,"STORE_CLOSED","ร้านพักรับออเดอร์");if(time(quote,"expires_at").isBefore(Instant.now()))throw new Problem(410,"QUOTE_EXPIRED","ราคาหมดอายุ กรุณาตรวจรายการใหม่");if(num(quote,"catalog_version")!=num(store,"catalog_version"))throw new Problem(409,"REQUOTE_REQUIRED","เมนูหรือราคามีการเปลี่ยน กรุณาตรวจรายการใหม่");boolean take=str(quote,"mode").equals("TAKEAWAY");if(take&&(req.pickupName==null||req.pickupName.isBlank()))throw Problem.bad("กรุณาระบุชื่อรับอาหาร");if(!take)visit(u,uuid(quote,"visit_id"));var calc=db.decode(quote.get("calculated"));var lines=maps(calc.get("lines"));TreeMap<UUID,Integer> amounts=new TreeMap<>();for(var l:lines)amounts.merge(UUID.fromString(str(l,"productId")),((Number)l.get("quantity")).intValue(),Integer::sum);
  for(var entry:amounts.entrySet()){var stock=db.one("SELECT s.*,p.active,p.sold_out FROM inventory_stock s JOIN product p ON p.id=s.product_id WHERE s.product_id=? FOR UPDATE OF s",entry.getKey());if(!Boolean.TRUE.equals(stock.get("active"))||Boolean.TRUE.equals(stock.get("sold_out"))||stock.get("available_qty")!=null&&num(stock,"available_qty")<entry.getValue())throw new Problem(409,"OUT_OF_STOCK","สินค้าบางรายการหมด กรุณาเลือกใหม่");if(stock.get("available_qty")!=null)db.jdbc.update("UPDATE inventory_stock SET available_qty=available_qty-?,version=version+1,updated_at=now() WHERE product_id=?",entry.getValue(),entry.getKey());}
  UUID id=UUID.randomUUID();String code=String.format("Q%06d",db.jdbc.queryForObject("SELECT nextval('order_code_seq')",Long.class));String pickup=Crypto.pin();Instant deadline=Instant.now().plusSeconds(600),reserve=deadline.plusSeconds(120);db.jdbc.update("INSERT INTO orders(id,code,customer_id,store_id,quote_id,visit_id,mode,subtotal_satang,packaging_fee_satang,total_satang,vat_registered_snapshot,pickup_name,pickup_code_hash,pickup_code_ciphertext,payment_deadline,reserve_deadline) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",id,code,u.id(),uuid(quote,"store_id"),req.quoteId,quote.get("visit_id"),str(quote,"mode"),calc.get("subtotalSatang"),calc.get("packagingFeeSatang"),calc.get("totalSatang"),false,req.pickupName,Crypto.hash(pickup),crypto.encrypt(pickup),Timestamp.from(deadline),Timestamp.from(reserve));
  for(var l:lines){UUID itemId=UUID.randomUUID();db.jdbc.update("INSERT INTO order_item(id,order_id,product_id,name_snapshot,unit_base_satang,unit_options_satang,quantity,line_total_satang,station,note) VALUES(?,?,?,?,?,?,?,?,?,?)",itemId,id,UUID.fromString(str(l,"productId")),str(l,"name"),l.get("unitBaseSatang"),l.get("unitOptionsSatang"),l.get("quantity"),l.get("lineTotalSatang"),str(l,"station"),str(l,"note"));for(var c:maps(l.get("options")))db.jdbc.update("INSERT INTO order_item_option(order_item_id,choice_id,group_snapshot,label_snapshot,price_delta_satang) VALUES(?,?,?,?,?)",itemId,UUID.fromString(str(c,"id")),str(c,"group"),str(c,"label"),c.get("priceDeltaSatang"));}
  for(var e:amounts.entrySet())db.jdbc.update("INSERT INTO inventory_reservation(order_id,product_id,quantity,status,expires_at) VALUES(?,?,?,'HELD',?)",id,e.getKey(),e.getValue(),Timestamp.from(reserve));db.event(id,null,"AWAITING_PAYMENT",u.id(),"Order created");var result=view(id,u,false);cache(u,"/orders",key,req,result);return result;
 }
 public Map<String,Object> view(UUID id,Auth.User u,boolean staff){var o=staff?db.one("SELECT * FROM orders WHERE id=?",id):db.one("SELECT * FROM orders WHERE id=? AND customer_id=?",id,u.id());var out=new LinkedHashMap<String,Object>();for(var pair:List.of("id:id","code:code","mode:mode","status:status","paymentStatus:payment_status","totalSatang:total_satang","subtotalSatang:subtotal_satang","packagingFeeSatang:packaging_fee_satang","pickupName:pickup_name","version:version")){String[] p=pair.split(":");out.put(p[0],o.get(p[1]));}out.put("currency","THB");out.put("createdAt",time(o,"created_at").toString());out.put("paymentDeadline",time(o,"payment_deadline").toString());if(!staff&&o.get("pickup_code_ciphertext")!=null)out.put("pickupCode",crypto.decrypt(str(o,"pickup_code_ciphertext")));List<Map<String,Object>> items=new ArrayList<>();for(var i:db.jdbc.queryForList("SELECT * FROM order_item WHERE order_id=? ORDER BY id",id)){items.add(Map.of("id",i.get("id"),"name",i.get("name_snapshot"),"quantity",i.get("quantity"),"lineTotalSatang",i.get("line_total_satang"),"station",i.get("station"),"note",str(i,"note"),"options",db.jdbc.queryForList("SELECT label_snapshot AS label FROM order_item_option WHERE order_item_id=? ORDER BY id",uuid(i,"id"))));}out.put("items",items);out.put("paymentAttempts",db.jdbc.queryForList("SELECT id,status FROM payment_attempt WHERE order_id=? ORDER BY created_at DESC",id));return out;}
 public Map<String,Object> list(Auth.User u,boolean staff){var rows=staff?db.jdbc.queryForList("SELECT id FROM orders ORDER BY created_at DESC LIMIT 100"):db.jdbc.queryForList("SELECT id FROM orders WHERE customer_id=? ORDER BY created_at DESC LIMIT 100",u.id());return Map.of("items",rows.stream().map(r->view(uuid(r,"id"),u,staff)).toList());}
 public Map<String,Object> tickets(){List<Map<String,Object>> result=new ArrayList<>();for(var t:db.jdbc.queryForList("SELECT t.*,o.code,o.mode FROM kitchen_ticket t JOIN orders o ON o.id=t.order_id WHERE o.status IN ('QUEUED','PREPARING','READY') ORDER BY t.created_at")){List<Map<String,Object>> items=new ArrayList<>();for(var i:db.jdbc.queryForList("SELECT * FROM order_item WHERE order_id=? AND station=?",uuid(t,"order_id"),str(t,"station")))items.add(Map.of("name",i.get("name_snapshot"),"quantity",i.get("quantity"),"note",str(i,"note"),"options",db.jdbc.queryForList("SELECT label_snapshot FROM order_item_option WHERE order_item_id=?",String.class,uuid(i,"id"))));result.add(Map.of("id",t.get("id"),"orderId",t.get("order_id"),"orderCode",t.get("code"),"mode",t.get("mode"),"station",t.get("station"),"status",t.get("status"),"version",t.get("version"),"createdAt",time(t,"created_at").toString(),"items",items));}return Map.of("items",result);}
 @Transactional public void transition(Auth.User u,UUID ticket,String target,long version){UUID oid=uuid(db.one("SELECT order_id FROM kitchen_ticket WHERE id=?",ticket),"order_id");var o=db.one("SELECT * FROM orders WHERE id=? FOR UPDATE",oid);var t=db.one("SELECT * FROM kitchen_ticket WHERE id=? FOR UPDATE",ticket);if(num(t,"version")!=version)throw new Problem(409,"STALE_VERSION","คิวนี้เปลี่ยนแล้ว กรุณาโหลดใหม่");if(!(target.equals("PREPARING")&&str(t,"status").equals("QUEUED")||target.equals("READY")&&str(t,"status").equals("PREPARING")))throw Problem.bad("เปลี่ยนสถานะนี้ไม่ได้");if(!Set.of("QUEUED","PREPARING").contains(str(o,"status")))throw new Problem(409,"INVALID_STATE","ออเดอร์ไม่ได้อยู่ในคิวทำอาหาร");db.jdbc.update("UPDATE kitchen_ticket SET status=?,version=version+1,started_at=CASE WHEN ?='PREPARING' THEN now() ELSE started_at END,ready_at=CASE WHEN ?='READY' THEN now() ELSE ready_at END WHERE id=?",target,target,target,ticket);boolean ready=db.jdbc.queryForObject("SELECT count(*) FROM kitchen_ticket WHERE order_id=? AND status<>'READY'",Integer.class,oid)==0;String next=ready?"READY":"PREPARING";db.jdbc.update("UPDATE orders SET status=?,version=version+1,updated_at=now() WHERE id=?",next,oid);db.event(oid,str(o,"status"),next,u.id(),"Kitchen update");db.audit(u.id(),"KITCHEN_"+target,oid);if(ready)notify(oid,"READY");}
 @Transactional public Map<String,Object> complete(Auth.User u,UUID id,long version,String pickupCode){var o=db.one("SELECT * FROM orders WHERE id=? FOR UPDATE",id);if(num(o,"version")!=version||!str(o,"status").equals("READY"))throw new Problem(409,"STALE_VERSION","ออเดอร์ยังไม่พร้อมหรือมีข้อมูลเปลี่ยน");if(str(o,"mode").equals("TAKEAWAY")&&!Crypto.equal(str(o,"pickup_code_hash"),Crypto.hash(Objects.toString(pickupCode,""))))throw Problem.bad("รหัสรับอาหารไม่ถูกต้อง");db.jdbc.update("UPDATE orders SET status='COMPLETED',version=version+1,completed_at=now(),updated_at=now() WHERE id=?",id);db.event(id,"READY","COMPLETED",u.id(),"Food handed over");db.audit(u.id(),"HANDOVER",id);return view(id,u,true);}
 void notify(UUID order,String milestone){db.jdbc.update("INSERT INTO outbox_event(topic,aggregate_id,dedupe_key,payload,expires_at) VALUES('LINE_STATUS',?,?,?::jsonb,now()+interval '2 hours') ON CONFLICT(dedupe_key) DO NOTHING",order,"line:"+order+":"+milestone,db.encode(Map.of("orderId",order,"milestone",milestone)));}
 void release(UUID order){for(var r:db.jdbc.queryForList("SELECT * FROM inventory_reservation WHERE order_id=? AND status='HELD' ORDER BY product_id FOR UPDATE",order)){db.jdbc.update("UPDATE inventory_stock SET available_qty=CASE WHEN available_qty IS NULL THEN NULL ELSE available_qty+? END,version=version+1 WHERE product_id=?",r.get("quantity"),r.get("product_id"));db.jdbc.update("UPDATE inventory_reservation SET status='RELEASED',updated_at=now() WHERE id=?",r.get("id"));}}
 @Transactional public void expire(UUID id){var o=db.one("SELECT * FROM orders WHERE id=? FOR UPDATE",id);if(!str(o,"status").equals("AWAITING_PAYMENT")||time(o,"payment_deadline").isAfter(Instant.now()))return;if(db.jdbc.queryForObject("SELECT count(*) FROM payment_attempt WHERE order_id=? AND status IN ('CREATING','UNKNOWN','PENDING','SUCCEEDED')",Integer.class,id)>0)return;release(id);db.jdbc.update("UPDATE orders SET status='EXPIRED',version=version+1 WHERE id=?",id);db.event(id,"AWAITING_PAYMENT","EXPIRED",null,"Payment deadline expired");}
}
